import fs from 'fs';

const path = 'src/App.jsx';
let app = fs.readFileSync(path, 'utf8');
const start = app.indexOf('const TIPS_DATA = [');
if (start < 0) throw new Error('TIPS_DATA not found');
const end = app.indexOf('\n];', start);
if (end < 0) throw new Error('TIPS_DATA closing bracket not found');
const block = app.slice(start, end);

const categories = ['dog','cat','health','life','food','training','safety','grooming'];
const ids = [...block.matchAll(/id:\s*"t(\d+)"/g)].map(m => Number(m[1]));
const titles = new Set([...block.matchAll(/title:\s*\{\s*ko:\s*"([^"]+)"/g)].map(m => m[1]));
if (!ids.length) throw new Error('PetInfo IDs not found');
const maxId = Math.max(...ids);
if (maxId < 322) throw new Error(`Expected dataset through at least t322, found t${maxId}`);

const candidates = [
  {category:'dog',featured:true,titleKo:'산책 후 발바닥 사이에 이물질이 없는지 확인해요',titleEn:'Check between paw pads after walks',summaryKo:'산책 뒤 작은 돌, 씨앗, 모래 같은 이물질이 끼지 않았는지 살펴요.',summaryEn:'After walks, check for small stones, seeds, sand, or other debris between the paw pads.',bodyKo:'산책을 마친 뒤 발바닥과 발가락 사이를 가볍게 확인하고 묻은 이물질은 부드럽게 제거하세요. 붉음, 상처, 계속 핥는 행동이나 절뚝거림이 보이면 상태를 자세히 살피고 필요하면 동물병원에 상담하세요.',bodyEn:'After a walk, gently inspect the paw pads and between the toes and remove loose debris. Redness, wounds, repeated licking, or limping should be checked and discussed with a veterinarian when needed.'},
  {category:'dog',featured:false,titleKo:'낯선 사람을 만날 때 먼저 다가가도록 강요하지 않아요',titleEn:'Do not force greetings with unfamiliar people',summaryKo:'반려견이 스스로 거리를 조절할 수 있게 하면 긴장을 줄이는 데 도움이 돼요.',summaryEn:'Allowing a dog to control distance can help reduce stress during unfamiliar greetings.',bodyKo:'낯선 사람 앞에서 뒤로 물러나거나 시선을 피한다면 억지로 가까이 데려가지 마세요. 편안한 거리를 유지하고 차분한 행동을 보상하면서 반려견이 스스로 접근할 시간을 주세요.',bodyEn:'If your dog backs away or avoids eye contact around someone unfamiliar, do not force an approach. Maintain a comfortable distance, reward calm behavior, and allow the dog to choose when to move closer.'},
  {category:'cat',featured:true,titleKo:'고양이 숨숨집은 출입구가 막히지 않게 배치해요',titleEn:'Keep cat hideaway entrances clear',summaryKo:'안전하게 드나들 수 있는 숨숨집은 고양이가 편안히 쉴 공간이 될 수 있어요.',summaryEn:'A hideaway with a clear entrance can provide a comfortable resting place for cats.',bodyKo:'숨숨집이나 박스를 벽에 너무 바짝 붙이거나 물건으로 입구를 가리지 마세요. 고양이가 주변을 살피고 쉽게 드나들 수 있도록 안정적인 위치에 두고, 억지로 꺼내지 않는 것이 좋아요.',bodyEn:'Avoid blocking the entrance of a cat hideaway with walls or objects. Place it in a stable location where the cat can enter and leave easily, and avoid pulling the cat out by force.'},
  {category:'cat',featured:false,titleKo:'고양이 장난감 끈은 놀이가 끝나면 치워둬요',titleEn:'Put string toys away after cat playtime',summaryKo:'끈이나 리본 장난감은 보호자와 놀 때 사용하고 끝난 뒤에는 보관해요.',summaryEn:'Use string and ribbon toys during supervised play and store them afterward.',bodyKo:'긴 끈, 리본, 실이 달린 장난감은 삼키거나 몸에 감길 위험이 있어 혼자 두고 놀게 하지 않는 것이 안전합니다. 놀이가 끝나면 손이 닿지 않는 곳에 보관하세요.',bodyEn:'Long strings, ribbons, and thread-like toys can be swallowed or become tangled around the body, so supervised use is safer. Store them out of reach when playtime ends.'},
  {category:'health',featured:true,titleKo:'평소 물 마시는 양이 크게 달라지면 기록해둬요',titleEn:'Track major changes in drinking habits',summaryKo:'평소보다 물을 훨씬 많이 또는 적게 마시는 변화는 관찰 기록이 도움이 돼요.',summaryEn:'Noting substantial increases or decreases in drinking can provide useful health information.',bodyKo:'물그릇을 채우는 횟수나 대략적인 섭취량을 평소와 비교해 보세요. 갑작스러운 변화가 며칠 이어지거나 소변량, 식욕, 활력 변화가 함께 나타나면 동물병원에 상담하는 것이 좋습니다.',bodyEn:'Compare how often the water bowl needs refilling or approximate intake with your pet’s normal pattern. If a major change persists or occurs with changes in urination, appetite, or energy, contact a veterinarian.'},
  {category:'health',featured:false,titleKo:'귀를 자주 긁거나 머리를 흔들면 귀 상태를 살펴요',titleEn:'Check the ears if scratching or head shaking increases',summaryKo:'반복적인 귀 긁기나 머리 흔들기는 불편함의 신호일 수 있어요.',summaryEn:'Frequent ear scratching or head shaking can signal discomfort.',bodyKo:'귀 주변의 붉음, 냄새, 분비물, 통증 반응이 있는지 확인하세요. 면봉을 깊이 넣거나 임의의 약을 사용하지 말고 증상이 반복되면 동물병원에서 원인을 확인하세요.',bodyEn:'Look for redness, odor, discharge, or tenderness around the ears. Avoid inserting cotton swabs deeply or using unprescribed medication, and seek veterinary evaluation if symptoms persist.'},
  {category:'life',featured:true,titleKo:'반려동물 휴식 공간은 사람 동선과 조금 떨어뜨려요',titleEn:'Place rest areas away from heavy foot traffic',summaryKo:'조용하고 방해가 적은 자리는 반려동물이 편안히 쉬는 데 도움이 돼요.',summaryEn:'A quiet, low-traffic resting spot can help pets relax more comfortably.',bodyKo:'현관이나 복도 한가운데처럼 사람이 자주 지나는 곳보다는 쉽게 접근하면서도 방해가 적은 위치에 침대나 방석을 두세요. 쉬고 있는 반려동물을 자주 깨우거나 만지지 않는 것도 중요합니다.',bodyEn:'Place beds or cushions somewhere accessible but away from busy entrances or hallways. It is also helpful to avoid repeatedly waking or touching a pet that is resting.'},
  {category:'life',featured:false,titleKo:'여행용 이동장은 평소에도 익숙한 공간으로 만들어줘요',titleEn:'Make the travel carrier familiar before trips',summaryKo:'이동장을 평소에 열어두면 이동 당일의 낯설음을 줄이는 데 도움이 돼요.',summaryEn:'Leaving the carrier accessible at home can make it feel less unfamiliar on travel days.',bodyKo:'이동장을 여행이나 병원 가는 날에만 꺼내기보다 평소에도 문을 열어 두고 익숙한 담요나 간식을 활용해 긍정적인 경험을 만들어 주세요. 억지로 밀어 넣는 방식은 가능한 피하세요.',bodyEn:'Rather than bringing out the carrier only for trips or vet visits, leave it open at home and use familiar bedding or treats to build positive associations. Avoid forcing the pet inside whenever possible.'},
  {category:'food',featured:true,titleKo:'간식도 하루 섭취량에 포함해 생각해요',titleEn:'Count treats as part of daily intake',summaryKo:'간식은 작아 보여도 여러 번 주면 하루 열량이 크게 늘 수 있어요.',summaryEn:'Small treats can add up when given repeatedly throughout the day.',bodyKo:'훈련 보상과 가족이 주는 간식까지 포함해 하루에 얼마나 주는지 확인하세요. 체중 관리가 필요하거나 처방식 중이라면 적절한 간식 종류와 양을 수의사와 상의하는 것이 좋습니다.',bodyEn:'Include training rewards and treats from all family members when considering daily intake. If weight management or a prescription diet is involved, ask a veterinarian about appropriate treat choices and amounts.'},
  {category:'food',featured:false,titleKo:'사료 보관통에는 새 사료를 붓기 전 남은 가루를 정리해요',titleEn:'Clean old crumbs before refilling food containers',summaryKo:'사료 보관통을 주기적으로 비우고 정리하면 오래된 잔여물이 섞이는 것을 줄일 수 있어요.',summaryEn:'Periodically emptying and cleaning food containers helps prevent old residue from mixing with fresh food.',bodyKo:'새 사료를 계속 덧붓기보다 기존 사료를 다 사용한 뒤 보관통의 가루와 기름기를 정리하고 충분히 말린 다음 채우세요. 사료 자체는 제품 포장에 안내된 보관 방법을 따르는 것이 좋습니다.',bodyEn:'Instead of continually topping off a container, use the remaining food, clean out crumbs and oily residue, dry the container thoroughly, and then refill it. Follow the storage instructions on the food packaging.'},
  {category:'training',featured:true,titleKo:'기다리기 훈련은 아주 짧은 시간부터 시작해요',titleEn:'Start wait training with very short durations',summaryKo:'처음부터 오래 기다리게 하기보다 짧은 성공을 여러 번 만드는 편이 좋아요.',summaryEn:'Short, repeated successes are easier than asking for a long wait immediately.',bodyKo:'1~2초처럼 짧게 기다린 뒤 바로 보상하고, 성공이 안정되면 시간을 조금씩 늘려 주세요. 실패가 잦아지면 다시 쉬운 단계로 돌아가 성공할 수 있게 조절하세요.',bodyEn:'Begin with a one- or two-second wait, reward promptly, and lengthen the duration gradually once success is consistent. If failures increase, return to an easier step.'},
  {category:'training',featured:false,titleKo:'이름을 부른 뒤 쳐다보면 바로 칭찬해요',titleEn:'Reward attention after saying your pet’s name',summaryKo:'이름을 들었을 때 보호자를 보는 행동을 보상하면 긍정적인 연결을 만들 수 있어요.',summaryEn:'Rewarding attention after the name is spoken can build a positive association.',bodyKo:'조용한 환경에서 이름을 한 번 부르고 반려동물이 쳐다보는 순간 칭찬이나 작은 보상을 주세요. 반응이 없을 때 이름을 계속 반복하기보다 자극이 적은 환경에서 다시 시도하세요.',bodyEn:'In a quiet setting, say the pet’s name once and reward the moment the pet looks toward you. If there is no response, avoid repeating the name continuously and try again with fewer distractions.'},
  {category:'safety',featured:true,titleKo:'창문 방충망만 믿고 반려동물을 두지 않아요',titleEn:'Do not rely on ordinary window screens for pet safety',summaryKo:'일반 방충망은 반려동물의 체중이나 충격을 견디도록 만들어진 안전장치가 아닐 수 있어요.',summaryEn:'Standard window screens may not be designed to withstand a pet’s weight or impact.',bodyKo:'창문을 열어둘 때는 반려동물이 밀거나 뛰어오를 수 있는 위치인지 확인하고, 필요한 경우 별도의 안전망이나 잠금장치를 사용하세요. 높은 곳의 추락 위험이 있는 창문은 특히 주의가 필요합니다.',bodyEn:'When windows are open, consider whether a pet can push against or jump onto the screen, and use appropriate guards or locks when needed. Take extra care with windows where a fall could occur.'},
  {category:'safety',featured:false,titleKo:'세제와 청소용품은 사용 후 바로 닫아 보관해요',titleEn:'Close and store cleaning products immediately after use',summaryKo:'청소용품은 핥거나 밟지 못하도록 사용 후 안전하게 치워요.',summaryEn:'Store cleaning products safely after use so pets cannot lick or step in them.',bodyKo:'바닥이나 욕실을 청소한 뒤 제품 뚜껑을 닫아 손이 닿지 않는 곳에 두고, 반려동물이 젖은 청소 구역에 바로 들어가지 않게 하세요. 제품 라벨의 환기와 건조 지침도 확인하세요.',bodyEn:'After cleaning floors or bathrooms, close product containers, store them out of reach, and keep pets away from wet areas until safe. Follow label directions for ventilation and drying.'},
  {category:'grooming',featured:true,titleKo:'발톱은 한 번에 많이 자르기보다 조금씩 관리해요',titleEn:'Trim nails gradually rather than taking off too much at once',summaryKo:'발톱 안쪽 혈관을 피하려면 익숙하지 않을 때는 조금씩 다듬는 편이 안전해요.',summaryEn:'Small, gradual trims can reduce the chance of cutting into the sensitive quick.',bodyKo:'발톱 구조가 잘 보이지 않거나 반려동물이 불안해한다면 한 번에 짧게 자르려 하지 말고 조금씩 진행하세요. 안전한 위치를 판단하기 어렵다면 수의사나 전문 미용사의 도움을 받는 것이 좋습니다.',bodyEn:'If the nail structure is difficult to see or the pet is anxious, avoid trying to shorten the nail dramatically in one session. Ask a veterinarian or professional groomer for help if you are unsure where it is safe to trim.'},
  {category:'grooming',featured:false,titleKo:'빗질 도구는 털 길이와 피부 상태에 맞춰 선택해요',titleEn:'Choose grooming tools for coat length and skin condition',summaryKo:'모든 빗이 모든 털에 맞는 것은 아니어서 자극이 적은 도구를 선택하는 것이 좋아요.',summaryEn:'Not every brush suits every coat, so choose tools that minimize skin irritation.',bodyKo:'털 길이와 밀도에 맞는 빗을 사용하고 피부를 세게 긁는 느낌이 들지 않도록 압력을 조절하세요. 빗질 뒤 붉음이나 통증 반응이 반복되면 도구나 방법을 바꾸고 피부 상태를 확인하세요.',bodyEn:'Use a brush suited to coat length and density and avoid excessive pressure on the skin. If redness or discomfort repeatedly follows brushing, change the tool or technique and assess the skin.'}
];

const fresh = candidates.filter(item => !titles.has(item.titleKo));
if (!fresh.length) {
  console.log('No new PetInfo items to add');
  process.exit(0);
}
if (fresh.length !== 16) throw new Error(`Expected 16 unique PetInfo candidates, got ${fresh.length}`);
if (new Set(fresh.map(x => x.category)).size !== categories.length) throw new Error('PetInfo category coverage incomplete');

let nextId = maxId + 1;
const lines = fresh.map(item => `\n  { id: "t${nextId++}", category: "${item.category}", featured: ${item.featured},\n    title: { ko: ${JSON.stringify(item.titleKo)}, en: ${JSON.stringify(item.titleEn)} },\n    summary: { ko: ${JSON.stringify(item.summaryKo)}, en: ${JSON.stringify(item.summaryEn)} },\n    body: { ko: ${JSON.stringify(item.bodyKo)}, en: ${JSON.stringify(item.bodyEn)} }, sourceDate: "2026-08-27" },`).join('');
app = app.slice(0, end) + lines + app.slice(end);
fs.writeFileSync(path, app);
console.log(`Added ${fresh.length} PetInfo items through t${nextId - 1}`);
